'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(v,d=1)=>Number.isFinite(v)?v.toLocaleString('ko-KR',{maximumFractionDigits:d,minimumFractionDigits:d}):'자료 없음';
const flag=c=>`<img class="flag-image" src="assets/flags/${c.iso2.toLowerCase()}.svg" alt="${esc(c.english)} flag">`;
const grade=v=>v?v.replace('0',''):'—';
const version=new URLSearchParams(location.search).get('version')||'latest';
const GRADES=['A+','A','A-','B+','B','B-','C+','C','C-','D+','D','D-'];
const COLORS=version==='historical'?['#453257','#614570','#7f6182','#9c8295','#b4a3aa','#cbc0b7','#ddd3bb','#d6c197','#c3a16f','#ac8158','#90634c','#704738']:['#205f59','#347b6c','#57947b','#7daa8b','#a7be96','#c8cda7','#e2d5ac','#e5c392','#dca675','#ce865e','#bc654e','#a5463f'];
const DONOR='#285f83',RECIPIENT='#bb653c',GRAY='#d9ded5';
const DIMS={country_results_framework:'국가 결과체계',forward_visibility:'중기 예측가능성',country_system_use:'국가 시스템 사용',alignment:'정합성',budget_inclusion:'예산 반영',strategy:'국가 주도 전략',inclusion:'포용적 참여',mutual_accountability:'상호 책무성',information_system:'정보·성과관리',ownership:'수원국 주도성',predictability:'원조 예측 가능성',accountability:'투명성·책무성'};
const COMPS={ownership:'수원국 계획과 사업목표',results_alignment:'수원국 성과체계 활용',government_data:'정부 통계·자료 활용'};
const LANG={English:'영어',French:'프랑스어',Spanish:'스페인어',Portuguese:'포르투갈어',Korean:'한국어',Japanese:'일본어',German:'독일어',Dutch:'네덜란드어',Khmer:'크메르어',Vietnamese:'베트남어',Lao:'라오어',Thai:'태국어',Chinese:'중국어',Arabic:'아랍어',Swahili:'스와힐리어',Bengali:'벵골어',Nepali:'네팔어',Hindi:'힌디어',Indonesian:'인도네시아어',Italian:'이탈리아어',Dzongkha:'종카어',Danish:'덴마크어',Swedish:'스웨덴어',Finnish:'핀란드어',Norwegian:'노르웨이어',Croatian:'크로아티아어',Hungarian:'헝가리어',Czech:'체코어',Slovak:'슬로바키아어',Lithuanian:'리투아니아어',Estonian:'에스토니아어',Icelandic:'아이슬란드어',Irish:'아일랜드어',Sinhala:'싱할라어',Tamil:'타밀어',Urdu:'우르두어',Filipino:'필리핀어'};
let data, countries, scored;
const roleLabel=r=>r==='donor'?'공여국':'수원국';
function roleTags(c){return c.roles.length?c.roles.map(r=>`<span class="role-tag ${r}">${roleLabel(r)}</span>`).join(''):'<span class="role-tag">조사 역할 미확인</span>';}
function rating(c,role){return c.ratings.find(r=>r.role===role)||c.ratings[0];}
function ratingColor(r){return r?.published_grade?COLORS[GRADES.indexOf(grade(r.published_grade))]:GRAY;}
function languages(c){return c.languages.map(x=>LANG[x]||x).join(' · ')||'자료 없음';}
function pop(c){return c.population?`${num(c.population.value,0)}명`:'자료 없음';}
function gdp(c){if(!c.gdp)return '자료 없음';return c.gdp.value>=1e12?`${num(c.gdp.value/1e12,2)}조 US$`:`${num(c.gdp.value/1e8,1)}억 US$`;}
function fact(label,value,note=''){return `<div><dt>${label}</dt><dd>${value}${note?`<small>${esc(note)}</small>`:''}</dd></div>`;}
function bounds(r){if(r?.historical)return '자료 없음 · 과거 참고';return r?.missingness_bounds?`${num(r.missingness_bounds[0])}–${num(r.missingness_bounds[1])}`:'자료 없음';}
function gradeDescription(r){if(r?.historical)return `과거 참고 · ${r.source_year}년 원자료 · 실험 등급`;if(!r||r.published_score==null)return '평가 유보 · 입력자료 부족';return r.v03_point_score==null?'공개 입력값 기준 시험 등급 · 하위결측으로 평가 유보':'연구용 시험 등급';}
function dimBars(r){if(!r)return '<p class="data-note">국가등급 입력자료가 없습니다.</p>';return Object.entries(r.dimensions).map(([key,v])=>`<div class="metric"><div><span>${DIMS[key]||esc(key)}</span><span>${num(v)}</span></div><div class="metric-track"><i style="width:${Number.isFinite(v)?v:0}%"></i></div></div>`).join('');}
function pairFor(a,b){return scored.find(p=>(p.donor===a&&p.recipient===b)||(p.donor===b&&p.recipient===a));}
function pairsOf(id){return scored.filter(p=>p.donor===id||p.recipient===id);}
function partnerIds(id){return [...new Set(pairsOf(id).map(p=>p.donor===id?p.recipient:p.donor))];}
function chemColor(score){const stops=version==='historical'?[[112,71,56],[156,115,82],[221,211,187],[158,131,157],[69,50,87]]:[[182,80,64],[201,143,98],[230,217,173],[160,197,164],[33,109,103]];const x=Math.max(0,Math.min(100,score))/25,i=Math.min(3,Math.floor(x)),t=x-i;return `rgb(${stops[i].map((v,k)=>Math.round(v*(1-t)+stops[i+1][k]*t)).join(',')})`;}
function gotoPair(p){location.href=`compare.html?lang=${atlasLanguage}&version=${version}&donor=${encodeURIComponent(p.donor)}&recipient=${encodeURIComponent(p.recipient)}`;}
function initMenu(){const b=$('.menu-toggle'),m=$('#menu');if(!b)return;b.addEventListener('click',()=>{m.hidden=!m.hidden;b.setAttribute('aria-expanded',String(!m.hidden));b.querySelector('span').textContent=m.hidden?'☰':'×';});m.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{m.hidden=true;b.setAttribute('aria-expanded','false');b.querySelector('span').textContent='☰';}));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!m.hidden){m.hidden=true;b.setAttribute('aria-expanded','false');b.querySelector('span').textContent='☰';b.focus();}});}
async function init(){initMenu();try{data=JSON.parse(JSON.stringify(window.ATLAS_DATA));prepareVersion();countries=new Map(data.countries.map(c=>[c.id,c]));scored=data.pairs.filter(p=>Number.isFinite(p.process_chemistry));if(document.body.dataset.page==='compare')initCompare();else initMap();initEnhancements();}catch(e){console.error(e);const target=$('#compare-content')||$('#selection-status');target.innerHTML='데이터를 불러오지 못했습니다. <button onclick="location.reload()">다시 시도</button>';}}
function initMap(){
const vs=$('#data-version');vs.value=version;vs.onchange=()=>{const u=new URL(location.href);u.searchParams.set('version',vs.value);location.href=u.href;};
$('#version-note').textContent=version==='historical'?'과거 참고 자료 · 원자료 연도 표시 · 최신 추정치와 직접 비교 불가':'최신 완전자료 33개국 · 계층모형 국가쌍 230개';
let mode=new URLSearchParams(location.search).get('mode')==='chem'?'chem':'grade',first=null,selected=null,panelOpen=false;const svg=$('#world-map'),tooltip=$('#map-tooltip'),eligible=new Set(scored.flatMap(p=>[p.donor,p.recipient]));
svg.innerHTML=`<defs>${COLORS.map((color,i)=>`<pattern id="grade-${i}" patternUnits="userSpaceOnUse" width="6" height="6" patternTransform="rotate(35)"><rect width="6" height="6" fill="${color}"/><path d="M0 0V6" stroke="#f7f7f2" stroke-width="1.4" opacity=".55"/></pattern>`).join('')}</defs><g id="countries"></g>`;
const layer=$('#countries');let nodes=new Map();
for(const f of data.features){const c=countries.get(f.id),el=document.createElementNS('http://www.w3.org/2000/svg',f.path?'path':'circle');el.dataset.id=f.id;el.setAttribute('class','country'+(f.path?'':' tiny'));el.setAttribute('role','button');if(f.path)el.setAttribute('d',f.path);else{el.setAttribute('cx',f.point[0]);el.setAttribute('cy',f.point[1]);el.setAttribute('r','2.8');}el.addEventListener('pointerenter',e=>showTip(c,el,e));el.addEventListener('pointermove',e=>moveTip(e.clientX,e.clientY));el.addEventListener('pointerleave',()=>hideTip(el));el.addEventListener('focus',()=>{const b=el.getBoundingClientRect();showTip(c,el,{clientX:b.x+b.width/2,clientY:b.y+b.height/2});});el.addEventListener('blur',()=>hideTip(el));el.addEventListener('click',()=>select(c.id));el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select(c.id);}});layer.append(el);nodes.set(c.id,el);}
function canSelect(id){return mode==='grade'||(first?(id===first||partnerIds(first).includes(id)):eligible.has(id));}
function hideTip(el){tooltip.hidden=true;el?.classList.remove('is-hover');}
function moveTip(x,y){tooltip.style.left=`${Math.max(8,Math.min(innerWidth-tooltip.offsetWidth-12,x+18))}px`;tooltip.style.top=`${Math.max(8,Math.min(innerHeight-tooltip.offsetHeight-12,y+18))}px`;}
function showTip(c,el,e){if(!canSelect(c.id))return;el.classList.add('is-hover');const r=rating(c);let value=grade(r?.published_grade),note=gradeDescription(r);if(mode==='chem'){if(first&&c.id!==first){const p=pairFor(first,c.id);value=`${num(p.process_chemistry)} / 100`;note=`협력과정 정합성 · 조사 사업 ${p.n_projects??'—'}건`;}else{value=c.roles.map(roleLabel).join(' · ');note=c.id===first?'선택한 국가 · 다시 클릭하면 선택 해제':`케미 탐색 가능 · 협력국 ${partnerIds(c.id).length}개`;}}tooltip.innerHTML=`<span>${flag(c)} ${esc(c.name)}</span><b>${value}</b><small>${note}</small>`;tooltip.hidden=false;moveTip(e.clientX,e.clientY);}
function closePanel(remember=true){panelOpen=false;$('#country-panel').hidden=true;$('.map-shell').classList.remove('panel-open');$('#panel-toggle').hidden=!(selected&&remember);$('#panel-toggle').textContent='›';$('#panel-toggle').setAttribute('aria-expanded','false');$('#panel-toggle').setAttribute('aria-label','국가 정보 패널 펼치기');}
function openPanel(id){selected=id;panelOpen=true;const c=countries.get(id),r=rating(c);$('#country-panel').hidden=false;$('.map-shell').classList.add('panel-open');$('#panel-toggle').hidden=false;$('#panel-toggle').textContent='‹';$('#panel-toggle').setAttribute('aria-expanded','true');$('#panel-toggle').setAttribute('aria-label','국가 정보 패널 접기');$('#panel-content').innerHTML=`<div class="panel-heading"><span class="flag" role="img" aria-label="${esc(c.name)} 국기">${flag(c)}</span><button id="close-panel" aria-label="국가 정보 닫기">×</button></div><h2 class="panel-name">${esc(c.name)}</h2><p class="english-name">${esc(c.english)}</p>${roleTags(c)}<div class="rating-block"><div><span>국가 협력관행 · ${r?roleLabel(r.role):'자료 없음'}</span><br><strong style="color:var(--ink);border-bottom:4px solid ${ratingColor(r)}">${grade(r?.published_grade)}</strong></div><span>공개 입력값 기준<br><b>${num(r?.published_score)}${r?.published_score!=null?' / 100':''}</b><br>${r?.historical?`과거 참고 · ${r.source_year}`:r?.round?'GPEDC '+r.round+' 라운드':''}</span></div><p class="data-note">${gradeDescription(r)}${r?.v03_point_score==null&&r?.published_score!=null?`<br>결측에 따른 가능한 점수: ${bounds(r)}`:''}</p><section class="panel-section"><h3>국가 기본정보</h3><a class="text-link" href="evidence.html?country=${c.id}">UNICEF · 기관 근거 보기 ↗</a><dl class="facts">${fact('수도',esc(c.capital||'자료 없음'))}${fact('언어',esc(languages(c)))}${fact('인구',pop(c),c.population?`${c.population.year} · ${c.population.source}`:'')}${fact('명목 GDP',gdp(c),c.gdp?`${c.gdp.year} · ${c.gdp.source}`:'')}${fact('조사 사업 수',`${c.projects}건`,'GPEDC 조사 표본 내 · 전수 사업 수 아님')}${fact('케미 탐색 협력국',`${partnerIds(id).length}개`,'세 성분의 관측이 있는 국가쌍')}</dl></section><section class="panel-section"><h3>네 영역의 협력관행</h3>${dimBars(r)}<p class="data-note">역할별 네 영역에 각각 25%를 부여한 시험 지표입니다.</p></section><section class="panel-section"><h3>데이터를 읽는 데 필요한 맥락</h3><dl class="facts">${fact('결측에 따른 점수 범위',bounds(r),'가정에 따른 범위 · 신뢰구간 아님')}${fact('가중치 변화 범위',r?.weight_scenario_p05_p95?r.weight_scenario_p05_p95.map(v=>num(v)).join('–'):'자료 없음',r?.historical?'15–35% 허용 가중치의 가능한 경계값':'가중치 시나리오 5–95백분위')}${fact('같은 등급 유지 비율',r?.same_grade_fraction!=null?num(r.same_grade_fraction*100)+'%':'자료 없음','시나리오 비율 · 등급이 참일 확률 아님')}</dl><p class="data-note">기준기간: ${esc(r?.observed_periods?.join(' / ')||'자료 없음')}<br>인구·GDP와 협력지표는 관측 연도가 서로 다를 수 있습니다.</p><a class="text-link" href="#method">방법론과 출처 <span>↗</span></a></section>${eligible.has(id)?'<button class="panel-cta" id="panel-chem">이 국가의 케미 탐색 <span>↗</span></button>':'<p class="data-note">계산 가능한 케미 자료가 아직 없습니다.</p>'}`;$('#panel-content').scrollTop=0;$('#close-panel').onclick=()=>{closePanel();nodes.get(id)?.focus();};if($('#panel-chem'))$('#panel-chem').onclick=()=>{setMode('chem');select(id);};updateColors();}
function select(id){if(!canSelect(id))return;tooltip.hidden=true;$('#search-results').hidden=true;$('#country-search').value='';if(mode==='grade'){openPanel(id);return;}if(!first){first=id;closePanel(false);render();}else if(first===id){first=null;render();}else{gotoPair(pairFor(first,id));}}
function updateColors(){for(const [id,el] of nodes){const c=countries.get(id),r=rating(c);let color=GRAY;if(mode==='grade'){color=ratingColor(r);if(r?.published_grade&&r.v03_point_score==null)color=`url(#grade-${GRADES.indexOf(grade(r.published_grade))})`;}else if(canSelect(id)){color=first&&id!==first?chemColor(pairFor(first,id).process_chemistry):(c.roles.includes('donor')?DONOR:RECIPIENT);}el.setAttribute('fill',color);el.classList.toggle('disabled',!canSelect(id));el.classList.toggle('selected',mode==='chem'?first===id:selected===id);el.setAttribute('tabindex',canSelect(id)?'0':'-1');el.setAttribute('aria-disabled',String(!canSelect(id)));el.setAttribute('aria-label',`${c.name}, ${mode==='grade'?grade(r?.published_grade)+' '+gradeDescription(r):first&&id!==first&&canSelect(id)?'케미 '+num(pairFor(first,id).process_chemistry):c.roles.map(roleLabel).join(' · ')||'케미 자료 없음'}`);}}
function render(){updateColors();$('#grade-mode').setAttribute('aria-pressed',String(mode==='grade'));$('#chem-mode').setAttribute('aria-pressed',String(mode==='chem'));$('#mode-title').textContent=mode==='grade'?'국가마다 다른, 협력의 모습.':'두 국가가 만나 만드는 가능성.';$('#mode-description').textContent=mode==='grade'?'국가에 커서를 올려 등급을 보고, 클릭해 자세히 살펴보세요.':first?'색으로 표시된 협력국을 선택하면 두 국가의 비교 페이지로 이동합니다.':'공여국 또는 수원국을 먼저 선택하세요. 함께한 국가들이 지도에 남습니다.';$('#reset').hidden=!first;$('#selection-status').innerHTML=mode==='grade'?'국가를 선택해 주세요':first?`<strong>${flag(countries.get(first))} ${esc(countries.get(first).name)}</strong><span>→ 협력국 ${partnerIds(first).length}개 중 선택</span>`:'① 첫 번째 국가 선택 → ② 협력국 선택';$('#coverage').textContent=mode==='grade'?`${data.countries.length}개 국가·지역 탐색 · ${data.countries.filter(c=>c.ratings.some(r=>r.published_grade)).length}개국 시험 등급 · 자료 미확보 국가는 회색`:`${eligible.size}개 국가 · ${scored.length}개 국가쌍 · 전 분야 조사 표본의 정합성`;$('#legend').innerHTML=mode==='grade'?`<div class="legend-label"><span>국가 협력관행 · 시험 등급</span><span>높음 → 낮음</span></div><div class="grade-legend">${GRADES.map((g,i)=>`<span><i style="background:${COLORS[i]}"></i>${g}</span>`).join('')}</div><div class="legend-extra"><span><i class="swatch" style="background:${GRAY}"></i>등급 자료 없음</span></div>`:first?`<div class="legend-label"><span>협력과정 정합성 · 케미 시험 점수</span><span>0 → 100</span></div><div class="gradient-scale"></div><div class="legend-extra"><span>낮음</span><span style="margin-left:auto">높음</span></div><div class="legend-extra"><span><i class="swatch" style="background:${countries.get(first).roles.includes('donor')?DONOR:RECIPIENT}"></i>선택한 국가</span><span><i class="swatch" style="background:${GRAY}"></i>선택 불가 · 계산 가능한 연결 없음</span></div>`:`<div class="chem-legend"><span><i class="swatch" style="background:${DONOR}"></i>공여국</span><span><i class="swatch" style="background:${RECIPIENT}"></i>수원국</span><span><i class="swatch" style="background:${GRAY}"></i>선택 불가</span></div><div class="legend-extra">양쪽 역할이 있는 국가는 공여국 색으로 표시 · 국가 선택 후 협력국만 활성화</div>`;}
function setMode(next){mode=next;first=null;closePanel(false);selected=null;tooltip.hidden=true;$('#search-results').hidden=true;$('#country-search').value='';render();const u=new URL(location.href);u.searchParams.set('mode',mode);try{history.replaceState(null,'',u);}catch{}}
$('#grade-mode').onclick=()=>setMode('grade');$('#chem-mode').onclick=()=>setMode('chem');$('#reset').onclick=()=>{first=null;render();};$('#panel-toggle').onclick=()=>panelOpen?closePanel():openPanel(selected);$$('[data-jump]').forEach(b=>b.onclick=()=>{setMode(b.dataset.jump);$('#atlas').scrollIntoView();});
const input=$('#country-search'),results=$('#search-results');input.addEventListener('input',()=>{const q=input.value.trim().toLowerCase();results.hidden=!q;if(!q)return;const matches=data.countries.filter(c=>(c.name.toLowerCase().includes(q)||c.english.toLowerCase().includes(q)||c.id.toLowerCase()===q||c.iso2.toLowerCase()===q)&&canSelect(c.id)).sort((a,b)=>a.name.localeCompare(b.name,'ko')).slice(0,18);results.innerHTML=matches.length?matches.map(c=>`<button data-country="${c.id}"><span>${flag(c)} ${esc(c.name)}</span><small>${mode==='grade'?grade(rating(c)?.published_grade):first&&first!==c.id?num(pairFor(first,c.id).process_chemistry):c.roles.map(roleLabel).join('·')}</small></button>`).join(''):'<p>선택 가능한 국가가 없습니다.</p>';results.querySelectorAll('button').forEach(b=>b.onclick=()=>select(b.dataset.country));});input.addEventListener('keydown',e=>{if(e.key==='ArrowDown'){e.preventDefault();results.querySelector('button')?.focus();}if(e.key==='Enter'){const btn=results.querySelector('button');if(btn){e.preventDefault();btn.click();}}if(e.key==='Escape')results.hidden=true;});results.addEventListener('keydown',e=>{const bs=[...results.querySelectorAll('button')],i=bs.indexOf(document.activeElement);if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();bs[(i+(e.key==='ArrowDown'?1:-1)+bs.length)%bs.length]?.focus();}if(e.key==='Escape'){results.hidden=true;input.focus();}});document.addEventListener('click',e=>{if(!e.target.closest('.search-wrap'))results.hidden=true;});document.addEventListener('keydown',e=>{if(e.key==='Escape'){tooltip.hidden=true;closePanel();}});window.addEventListener('scroll',()=>{tooltip.hidden=true;},{passive:true});render();}
function initCompare(){const params=new URLSearchParams(location.search);let donor=params.get('donor'),recipient=params.get('recipient');const donors=[...new Set(scored.map(p=>p.donor))].map(id=>countries.get(id)).sort((a,b)=>a.name.localeCompare(b.name,'ko'));if(!donors.some(c=>c.id===donor))donor=null;if(!scored.some(p=>p.donor===donor&&p.recipient===recipient))recipient=null;
const opts=(arr,id,placeholder)=>`<option value="">${placeholder}</option>`+arr.map(c=>`<option value="${c.id}" ${c.id===id?'selected':''}>${esc(c.name)}</option>`).join('');
function selectors(){const receivers=[...new Set(scored.filter(p=>p.donor===donor).map(p=>p.recipient))].map(id=>countries.get(id)).sort((a,b)=>a.name.localeCompare(b.name,'ko'));$('#compare-selectors').innerHTML=`<div class="selector"><label for="donor-select">01 / 공여국</label><select id="donor-select">${opts(donors,donor,'공여국을 선택하세요')}</select><small>공여국을 먼저 바꾸고 새 협력국을 선택할 수 있습니다.</small></div><div class="selector"><label for="recipient-select">02 / 수원국</label><select id="recipient-select" ${donor?'':'disabled'}>${opts(receivers,recipient,donor?'협력국을 선택하세요':'공여국을 먼저 선택하세요')}</select><small>${donor?`${esc(countries.get(donor).name)} 기준 · 선택 가능한 협력국 ${receivers.length}개`:'첫 번째 국가의 협력 경험에 맞춰 목록이 바뀝니다.'}</small></div>`;$('#donor-select').onchange=e=>{donor=e.target.value||null;const kept=scored.some(p=>p.donor===donor&&p.recipient===recipient);if(!kept)recipient=null;render(kept?'공여국을 변경했습니다.':'공여국을 변경했습니다. 이 국가와 협력 경험이 있는 수원국을 선택해 주세요.');$('#recipient-select').focus();};$('#recipient-select').onchange=e=>{recipient=e.target.value||null;render(recipient?'두 국가의 비교 내용을 업데이트했습니다.':'협력국을 선택해 주세요.');$('#recipient-select').focus();};}
function row(label,vals){return `<div class="comparison-row"><h3>${label}</h3><div class="comparison-cells">${vals.map(v=>`<div class="comparison-cell">${v}</div>`).join('')}</div>`;}
function render(message=''){selectors();$('#compare-message').textContent=message;const u=new URL(location.href);for(const [key,value] of [['donor',donor],['recipient',recipient]])value?u.searchParams.set(key,value):u.searchParams.delete(key);try{history.replaceState(null,'',u);}catch{}const p=scored.find(p=>p.donor===donor&&p.recipient===recipient);if(!p){$('#compare-content').innerHTML=`<div class="empty-state"><h2>${donor?`${esc(countries.get(donor).name)}의 협력국을 선택하세요.`:'어떤 두 국가를 살펴볼까요?'}</h2><p>사업 기록과 계산 가능한 정합성 점수가 있는 국가쌍만 비교할 수 있습니다.</p></div>`;document.title='두 국가의 연결 — 3-Trillion';return;}
const cs=[countries.get(donor),countries.get(recipient)],rs=cs.map((c,i)=>rating(c,i?'recipient':'donor'));document.title=`${cs[0].name} · ${cs[1].name} — 3-Trillion`;$('.back-map').href=`index.html?mode=chem&version=${version}#atlas`;
$('#compare-content').innerHTML=`<section class="country-heroes" aria-label="선택한 두 국가">${cs.map((c,i)=>`<article class="country-hero"><span class="flag" role="img" aria-label="${esc(c.name)} 국기">${flag(c)}</span><h2>${esc(c.name)}</h2><p class="english-name">${esc(c.english)}</p><span class="role-tag ${i?'recipient':'donor'}">${i?'수원국':'공여국'}</span></article>`).join('')}</section><section class="chemistry-summary"><div><span class="eyebrow">THE CHEMISTRY / RESEARCH ESTIMATE</span><h2>함께하는 과정의 정합성</h2><div class="big-score">${num(p.process_chemistry)}<small>/ 100</small></div><p class="score-caption">협력과정·성과관리 정합성 · 연구용 시험 점수</p></div><div class="score-detail"><p>수원국의 계획을 공유하고, 같은 성과체계와 정부 자료를 활용하는 정도를 살펴봅니다.</p><dl class="facts">${fact('조건부 불확실성 구간',p.conditional_95_union_bound?p.conditional_95_union_bound.map(v=>num(v)).join('–'):'자료 없음 · 과거 집계비율','95% 결합 경계 · 모형 및 초모수 조건부')}${fact('조사에 포함된 사업',`${p.n_projects??'—'}건`,'사업 수는 전수 실적이 아닌 조사 표본')}${fact('관측 기준기간',esc(p.reporting_periods.join(' / ')))}${fact('분야 범위','전 분야 조사 표본')}</dl></div></section><section class="comparison-section"><h2>국가 기본정보</h2>${row('수도',cs.map(c=>esc(c.capital||'자료 없음')))}${row('언어',cs.map(c=>esc(languages(c))))}${row('인구',cs.map(c=>`${pop(c)}<small>${c.population?`${c.population.year} · ${esc(c.population.source)}`:'확인된 자료 없음'}</small>`))}${row('명목 GDP',cs.map(c=>`${gdp(c)}<small>${c.gdp?`${c.gdp.year} · ${esc(c.gdp.source)}`:'확인된 자료 없음'}</small>`))}${row('개발협력 역할',cs.map((c,i)=>`${i?'수원국':'공여국'}<small>이 국가쌍에서의 역할${c.roles.length>1?' · 다른 관계에서는 공여·수원 양쪽 역할 관측':''}</small>`))}${row('조사 사업 수',cs.map(c=>`${c.projects}건<small>GPEDC 수집 표본 전체에서 확인한 건수</small>`))}${row('케미를 살펴볼 수 있는 협력국',cs.map(c=>`${partnerIds(c.id).length}개<small>세 성분에 직접 관측이 있는 국가쌍</small>`))}</section><section class="comparison-section"><h2>국가 협력관행</h2>${row('국가 등급 · 공개 입력값 기준',rs.map(r=>`<div class="grade-value" style="color:var(--ink);border-bottom:4px solid ${ratingColor(r)}">${grade(r?.published_grade)}</div><small>${gradeDescription(r)}<br>${num(r?.published_score)}${r?.published_score!=null?' / 100':''}</small>`))}${row('역할별 네 영역',rs.map(r=>dimBars(r)))}${row('결측에 따른 가능한 점수 범위',rs.map(r=>`${bounds(r)}<small>미관측 항목에 대한 가정 기반 범위 · 신뢰구간 아님</small>`))}${row('가중치 변화에 따른 점수 범위',rs.map(r=>`${r?.weight_scenario_p05_p95?r.weight_scenario_p05_p95.map(v=>num(v)).join('–'):'자료 없음'}<small>가중치 시나리오 5–95백분위</small>`))}${row('기준기간',rs.map(r=>`<small>${esc(r?.observed_periods?.join(' / ')||'자료 없음')}<br>GPEDC ${r?.round||2026} 공개 라운드</small>`))}</section><section class="comparison-section"><h2>케미 점수의 세 가지 구성</h2><div class="component-grid">${Object.entries(p.components).map(([key,v])=>`<article><h3>${COMPS[key]}</h3><div class="component-score">${num(v.posterior.mean*100)}</div><p>관측 사업 ${v.n_projects??'—'}건<br>성분별 조건부 95% 구간<br>${v.posterior.interval_95.length?v.posterior.interval_95.map(x=>num(x*100)).join('–'):'자료 없음'}</p></article>`).join('')}</div><p class="data-note">세 성분의 사후평균에 같은 가중치를 부여합니다. 전체 점수의 구간은 성분별 구간을 단순 평균한 값이 아닙니다.</p></section><section class="comparison-section"><h2>함께한 사업, 기록으로 살펴보기</h2><div class="project-filter"><span>조사 사업 ${p.projects.length}건 · 원문 사업명 · 전 분야</span><label><span class="sr-only">사업명 검색</span><input id="project-search" type="search" placeholder="사업명으로 검색"></label></div><div class="project-list" id="project-list"></div><p class="data-note">GPEDC 설계·관리 조사에 포함된 사업입니다. 완료 사업의 독립적인 효과성 평가나 전수 시행사업 목록이 아닙니다.</p></section>`;
function renderProjects(query=''){const ps=p.projects.filter(x=>x.title.toLowerCase().includes(query.toLowerCase()));$('#project-list').innerHTML=ps.length?ps.map((x,i)=>`<details class="project-item"><summary><span>${String(i+1).padStart(2,'0')}</span><b>${esc(x.title)}</b><span>＋</span></summary><p>보고기간: ${esc(x.period||'미기재')}<br>승인일: ${esc(x.approved?x.approved.slice(0,10):'미기재')}<br>조사 레코드: ${esc(x.id)}</p><div class="project-components">${Object.entries(x.components).map(([k,v])=>`<span>${COMPS[k]}<br><strong>${Number.isFinite(v.k)&&Number.isFinite(v.n)?`${v.k} / ${v.n}`:'관측 없음'}</strong></span>`).join('')}</div><p>K/N은 목표·지표의 정합성 관측값이며 사업 성공 횟수가 아닙니다.</p></details>`).join(''):'<p class="data-note">검색어와 일치하는 사업이 없습니다.</p>';}
if(p.historical){$('#project-list').innerHTML=`<p class="data-note">과거 참고 · ${p.source_year}년 · 원본 시트 ${esc(p.source_sheet)} · 행 ${p.source_row}. 공표된 집계비율을 사용했습니다. 사업별 원문 목록과 신뢰구간은 제공되지 않습니다.</p>`;}else renderProjects();$('#project-search').oninput=e=>renderProjects(e.target.value);initEnhancements();}
render(!donor||!recipient?'국가를 순서대로 선택해 비교를 시작하세요.':'');}
function prepareVersion(){document.body.classList.toggle('historical',version==='historical');
const old=data.pairs;data.pairs=[];data.countries.forEach(c=>{c.ratings=[];c.projects=0;});
for(const g of data.gradeRegistry){if((version==='historical')!==(g.version!=='v03'))continue;const c=data.countries.find(c=>c.id===g.iso3);if(!c)continue;
c.ratings.push(g.source_record||{role:g.role,round:g.monitoring_round,historical:true,source_year:g.source_year,published_grade:g.grade,published_score:g.score,v03_point_score:g.score,dimensions:Object.fromEntries(Object.entries(g.dimensions).map(([k,v])=>[k,v*100])),weight_scenario_p05_p95:g.weight_sensitivity_15_to_35_bounds,observed_periods:[String(g.source_year)]});}
for(const q of data.chemistryRegistry){if(q.partner_type!=='Bilateral'||(version==='historical')!==(q.version!=='process-posterior-v1'))continue;
let p;if(q.source_record){p=old.find(p=>p.donor===q.donor_iso3&&p.recipient===q.recipient_iso3);}else{p={...q,historical:true,donor:q.donor_iso3,recipient:q.recipient_iso3,process_chemistry:q.chemistry,n_projects:Number(q.project_count_reported)||null,projects:[],reporting_periods:[String(q.source_year)],conditional_95_union_bound:null,components:Object.fromEntries(Object.entries(q.components).map(([k,v])=>[k,{n_projects:null,posterior:{mean:v,interval_95:[]}}]))};}if(p)data.pairs.push(p);}
for(const p of data.pairs){for(const id of [p.donor,p.recipient]){const c=data.countries.find(c=>c.id===id);if(c)c.projects+=p.n_projects||0;}}
}
function initEnhancements(){
if(window.renderMethods)renderMethods();
if(version==='historical'){
 const note=$('#compare-message');if(note)note.textContent='과거 참고 · 집계비율의 단순 평균 · 최신 계층모형 추정치와 직접 비교 불가';
 if($('.score-caption'))$('.score-caption').textContent='과거 참고 · '+(data.pairs.find(p=>location.search.includes('donor='+p.donor)&&location.search.includes('recipient='+p.recipient))?.source_year||'')+'년 원자료 · 서술형 정합성';
 $$('.component-grid article p').forEach(n=>n.textContent='공표된 집계비율 · 사업별 분모와 조건부 구간 없음');
 $$('.comparison-cell small').forEach(n=>{if(n.textContent==='가중치 시나리오 5–95백분위')n.textContent='15–35% 허용 가중치의 가능한 경계값';});if($('.component-grid + .data-note'))$('.component-grid + .data-note').textContent='세 집계비율의 단순 평균입니다. 최신 계층모형의 사후평균과 구분됩니다.';
}

const art=$('.wordmark');if(art&&!matchMedia('(prefers-reduced-motion: reduce)').matches){art.addEventListener('pointermove',e=>{const b=art.getBoundingClientRect();art.querySelectorAll('span').forEach((s,i)=>{const x=b.width*(i+.5)/8,energy=Math.max(0,1-Math.abs(e.clientX-b.left-x)/(b.width*.28));s.style.transform=`translateY(${Math.sin(i*1.5+e.clientY*.02)*energy*18}px) rotate(${(e.clientX-b.left-x)/b.width*energy*12}deg)`;s.style.backgroundPosition=`0 ${energy*35}px`;});});art.addEventListener('pointerleave',()=>art.querySelectorAll('span').forEach(s=>{s.style.transform='';s.style.backgroundPosition='';}));}
applyLanguage();
}
init();
